	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading CSV: %v\n", err)
		os.Exit(1)
	}

	// Check if there is data beyond the header
	if len(records) <= 1 {
		fmt.Println("[]")
		return
	}

	var people []Person

	// Process rows (skipping the header at index 0)
	for i := 1; i < len(records); i++ {
