	// The prompt asks for the sequence starting 1, 1, 2, 3, 5...
	// We continue while the current Fibonacci number does not exceed N.
	for b <= n {
		fmt.Println(b)

		// Calculate next Fibonacci number
		next := a + b
		a = b
		b = next
	}
}
